-- Recuperada da producao (supabase_migrations.schema_migrations).
--
-- Esta migration JA ESTA APLICADA no banco de producao, mas nao tinha arquivo
-- no repositorio: o check "Supabase Preview" falhava em todo push para a main
-- com "Remote migration versions not found in local migrations directory",
-- e a cadeia local nao reconstruia a producao.
--
-- O SQL abaixo e o que a propria producao registrou ter executado.
-- versao: 20260321125922
-- nome:   salespro_mig_007_security_bi_supply_remaining

-- Security
CREATE TABLE IF NOT EXISTS public.user_roles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role app_role NOT NULL DEFAULT 'salesperson', created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), UNIQUE(user_id, role));
CREATE TABLE IF NOT EXISTS public.permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, description text, resource text NOT NULL, action text NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT now(), UNIQUE(resource, action));
CREATE TABLE IF NOT EXISTS public.role_permissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), role app_role NOT NULL, permission_id uuid NOT NULL REFERENCES public.permissions(id) ON DELETE CASCADE, created_at timestamp with time zone NOT NULL DEFAULT now(), UNIQUE(role, permission_id));
CREATE TABLE IF NOT EXISTS public.login_attempts (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, email TEXT NOT NULL, ip_address TEXT, user_agent TEXT, success BOOLEAN DEFAULT FALSE, failure_reason TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.blocked_ips (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, ip_address TEXT NOT NULL UNIQUE, reason TEXT NOT NULL, blocked_by UUID REFERENCES auth.users(id), blocked_at TIMESTAMPTZ DEFAULT NOW(), expires_at TIMESTAMPTZ, is_permanent BOOLEAN DEFAULT FALSE, block_count INTEGER DEFAULT 1, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.ip_whitelist (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, ip_address TEXT NOT NULL UNIQUE, description TEXT, added_by UUID REFERENCES auth.users(id), created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.rate_limit_settings (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, action TEXT NOT NULL UNIQUE, max_requests INTEGER NOT NULL DEFAULT 100, window_seconds INTEGER NOT NULL DEFAULT 3600, block_duration_seconds INTEGER NOT NULL DEFAULT 3600, is_active BOOLEAN DEFAULT TRUE, created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.rate_limit_logs (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, identifier TEXT NOT NULL, identifier_type TEXT NOT NULL DEFAULT 'ip', action TEXT NOT NULL, request_count INTEGER DEFAULT 1, window_start TIMESTAMPTZ DEFAULT NOW(), window_end TIMESTAMPTZ, blocked BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.active_sessions (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, session_token TEXT, ip_address TEXT, user_agent TEXT, device_info JSONB DEFAULT '{}', last_activity TIMESTAMPTZ DEFAULT NOW(), refresh_count INTEGER DEFAULT 0, last_refresh_at TIMESTAMPTZ, max_lifetime_hours INTEGER DEFAULT 24, created_at TIMESTAMPTZ DEFAULT NOW(), expires_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS public.known_devices (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, device_fingerprint TEXT NOT NULL, device_name TEXT, browser TEXT, os TEXT, is_trusted BOOLEAN DEFAULT FALSE, first_seen TIMESTAMPTZ DEFAULT NOW(), last_seen TIMESTAMPTZ DEFAULT NOW(), created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.login_alerts (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, alert_type TEXT NOT NULL, ip_address TEXT, device_info JSONB DEFAULT '{}', is_read BOOLEAN DEFAULT FALSE, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.access_denied_logs (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE SET NULL, user_email TEXT, attempted_path TEXT NOT NULL, required_role TEXT, user_role TEXT, ip_address TEXT, user_agent TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.security_alert_settings (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE UNIQUE, notify_new_device BOOLEAN NOT NULL DEFAULT true, notify_failed_login BOOLEAN NOT NULL DEFAULT true, notify_password_change BOOLEAN NOT NULL DEFAULT true, notify_role_change BOOLEAN NOT NULL DEFAULT true, max_failed_attempts INTEGER NOT NULL DEFAULT 5, alert_cooldown_minutes INTEGER NOT NULL DEFAULT 30, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now(), updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.security_alert_history (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, alert_type TEXT NOT NULL, severity TEXT NOT NULL DEFAULT 'medium' CHECK (severity IN ('low','medium','high','critical')), details JSONB DEFAULT '{}', ip_address TEXT, is_read BOOLEAN NOT NULL DEFAULT false, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.circuit_breaker_events (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, circuit_name TEXT NOT NULL, event_type TEXT NOT NULL CHECK (event_type IN ('opened','closed','half_open')), failure_count INTEGER DEFAULT 0, last_failure_reason TEXT, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS public.user_mfa_settings (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, totp_enabled BOOLEAN DEFAULT FALSE, totp_secret TEXT, totp_verified_at TIMESTAMPTZ, sms_enabled BOOLEAN DEFAULT FALSE, phone_number TEXT, phone_verified_at TIMESTAMPTZ, backup_codes TEXT[], backup_codes_generated_at TIMESTAMPTZ, preferred_method TEXT DEFAULT 'totp' CHECK (preferred_method IN ('totp','sms')), created_at TIMESTAMPTZ DEFAULT NOW(), updated_at TIMESTAMPTZ DEFAULT NOW(), UNIQUE(user_id));
CREATE TABLE IF NOT EXISTS public.mfa_verification_attempts (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, method TEXT NOT NULL CHECK (method IN ('totp','sms')), success BOOLEAN DEFAULT FALSE, ip_address TEXT, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.sms_verification_codes (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, phone_number TEXT NOT NULL, code TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, used BOOLEAN DEFAULT FALSE, attempts INTEGER DEFAULT 0, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.reauthentication_requests (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, action TEXT NOT NULL, status TEXT DEFAULT 'pending' CHECK (status IN ('pending','verified','expired','failed')), ip_address TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), expires_at TIMESTAMPTZ, verified_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS public.webauthn_credentials (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, credential_id TEXT NOT NULL UNIQUE, public_key TEXT NOT NULL, sign_count INTEGER DEFAULT 0, device_name TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), last_used_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS public.webauthn_challenges (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, challenge TEXT NOT NULL, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS public.password_reset_requests (id UUID DEFAULT gen_random_uuid() PRIMARY KEY, user_id UUID REFERENCES auth.users(id) ON DELETE CASCADE, email TEXT NOT NULL, token TEXT NOT NULL UNIQUE, status TEXT DEFAULT 'pending' CHECK (status IN ('pending','completed','expired')), ip_address TEXT, created_at TIMESTAMPTZ DEFAULT NOW(), expires_at TIMESTAMPTZ, completed_at TIMESTAMPTZ);
